const i = (name,cls='') => {const icon=iconNodes[name];if(!icon)return '';const attrs=Object.entries({...icon[1],'stroke-width':1.65}).map(([k,v])=>`${k}="${v}"`).join(' ');return `<svg ${attrs} class="lucide ${cls}" aria-hidden="true">${icon[2].map(([tag,attrs])=>`<${tag} ${Object.entries(attrs).map(([k,v])=>`${k}="${v}"`).join(' ' )}></${tag}>`).join('')}</svg>`;};
const btn=(action,icon,label,cls='',attrs='')=>`<button type="button" data-action="${action}" class="${cls}" ${label&&!attrs.includes('aria-label=')?`aria-label="${label.replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}"`:''} ${attrs}>${icon?i(icon):''}${label?`<span>${label}</span>`:''}</button>`;
const iconbtn=(action,icon,label,cls='',attrs='')=>btn(action,icon,'',`icon-btn ${cls}`,`aria-label="${e(label)}" title="${e(label)}" ${attrs}`);
