function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(saveTimer);saveTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
async function safe(fn){try{return await fn();}catch(error){console.error(error);toast(error?.name==='QuotaExceededError'?'Der Gerätespeicher ist voll. Bitte eine Sicherung exportieren und Speicher freigeben.':error?.message || 'Die Aktion konnte nicht gespeichert werden.');}}
