function empty(icon,title,text,action='import',label='Bücher importieren'){return `<div class="empty">${i(icon)}<h2>${e(title)}</h2><p>${e(text)}</p>${action?btn(action,'plus',label,'primary'):''}</div>`;}
function progress(book){return `<span class="progress-track"><span style="width:${percentage(book)}%"></span></span>`;}
function cover(book,cls=''){return `<img class="cover ${cls}" src="${e(book.cover || coverSVG({title:book.title,short:book.title.match(/.{1,17}(?:\s|$)/g)?.slice(0,4).join('\n') || book.title.slice(0,17),color:'#dcd7c5',ink:'#465442',art:'lines'}))}" alt="Cover: ${e(book.title)}" loading="lazy">`;}
function folderOptions(selected=null,exclude=null){return `<option value="">Keine übergeordnete Collection</option>`+state.folders.filter(f=>!exclude || !descendants(state.folders,exclude).has(f.id)).map(f=>`<option value="${e(f.id)}" ${selected===f.id?'selected':''}>${e(folderPath(state.folders,f.id))}</option>`).join('');}
function folderTree(parent=null,depth=0){return state.folders.filter(f=>f.parent===parent).map(f=>{
  const children=descendants(state.folders,f.id), count=state.books.filter(b=>b.collections.some(c=>children.has(c))).length;
  return `<div class="folder-row" style="--depth:${depth}">${btn(`collection:${f.id}`,'folder',e(f.name),`nav-item ${state.view===f.id?'active':''}`,`data-folder="${e(f.id)}"`)}<span class="nav-count">${count}</span>${iconbtn(`folder-menu:${f.id}`,'ellipsis',`${f.name} bearbeiten`,'folder-menu')}</div>${folderTree(f.id,depth+1)}`;
}).join('');}
