function libraryBooks(){
  let books=state.books;
  if (state.view==='reading') books=books.filter(b=>b.status==='reading');
  if (state.view==='favorites') books=books.filter(b=>b.favorite);
  if (state.view==='finished') books=books.filter(b=>b.status==='finished');
  if (state.folders.some(f=>f.id===state.view)) {const ids=descendants(state.folders,state.view);books=books.filter(b=>b.collections.some(c=>ids.has(c)));}
  if(state.format!=='all') books=books.filter(b=>state.format==='EPUB'?b.format!=='PDF':b.format==='PDF');
  if(state.sort==='title') return [...books].sort((a,b)=>a.title.localeCompare(b.title,'de'));
  if(state.sort==='progress') return [...books].sort((a,b)=>percentage(b)-percentage(a));
  return [...books].sort((a,b)=>b.updated-a.updated);
}
function bookCard(book,index=0){return `<article class="book-card" style="--book-order:${Math.min(index,8)}" draggable="true" data-book="${e(book.id)}"><div class="book-cover-wrap"><button class="cover-button" data-action="open:${book.id}" aria-label="${e(book.title)} lesen">${cover(book)}</button>${book.favorite?`<span class="favorite-badge">${i('heart')}</span>`:''}${iconbtn(`book-menu:${book.id}`,'ellipsis','Buchoptionen','cover-menu')}</div><div class="book-caption"><button data-action="open:${book.id}" class="book-title">${e(book.title)}</button><p>${e(book.author)}</p>${book.tags?.length?`<p class="book-tags">${e(book.tags.slice(0,3).join(' · '))}</p>`:''}${book.targetPage?`<p class="book-target">Leseziel: ${book.format==='PDF'?'S.':'Abs.'} ${book.targetPage}${book.targetDate?` · ${e(book.targetDate)}`:''}</p>`:''}<div class="book-meta"><span>${book.format==='DEMO'?'LESEPROBE':book.format}</span><span>${book.status==='finished'?i('circle-check')+' Gelesen':book.started?percentage(book)+' %':'Neu'}</span></div>${progress(book)}</div></article>`;}
function bookRow(book,table=false){return `<div class="book-row ${table?'table-row':''}" data-book="${e(book.id)}"><button class="row-book" data-action="open:${book.id}">${cover(book)}<span><strong>${e(book.title)}</strong><small>${e(book.author)}</small></span></button><span class="row-format">${book.format==='DEMO'?'Leseprobe':book.format}</span><span class="status-pill ${book.status}">${statusNames[book.status]}</span><div class="row-progress">${progress(book)}<small>${percentage(book)} %</small></div>${iconbtn(`book-menu:${book.id}`,'ellipsis','Buchoptionen')}</div>`;}
