function textAtPoint(x,y){
  let node,offset;
  if(document.caretPositionFromPoint){const p=document.caretPositionFromPoint(x,y);node=p?.offsetNode;offset=p?.offset;}
  else{const r=document.caretRangeFromPoint?.(x,y);node=r?.startContainer;offset=r?.startOffset;}
  if(node?.nodeType!==Node.TEXT_NODE||!node.parentElement.closest('#epub-page,.textLayer'))return false;
  for(const index of [offset,offset-1]){if(index<0||index>=node.length||!node.textContent[index]?.trim())continue;const r=document.createRange();r.setStart(node,index);r.setEnd(node,index+1);for(const b of r.getClientRects())if(x>=b.left-2&&x<=b.right+2&&y>=b.top&&y<=b.bottom)return true;}
  return false;
}
